function compilerRetrievalLimits(retrieval: BrainRetrievalResult): string | undefined {
  const unavailable = compilerHasUnavailableEvidence(retrieval.diagnostics);
  const budgetLimited = retrieval.omissions.some(({ reason }) =>
    ["byte_limit", "content_byte_limit", "delivery_byte_limit", "item_limit"].includes(reason),
  ) || [
    "byte_budget_exhausted", "content_budget_exhausted", "delivery_budget_exhausted", "item_budget_exhausted",
  ].includes(retrieval.stop.reason) || retrieval.evidence.some(({ selectionReasons }) =>
    selectionReasons.some((reason) =>
      ["hard_limit_excerpt", "content_limit_excerpt", "delivered_limit_excerpt"].includes(reason)),
  );
  const messages = [
    ...(unavailable ? [RETRIEVAL_LIMIT_MESSAGES.unavailable]
      : retrieval.stop.reason === "provider_degraded" ? [RETRIEVAL_LIMIT_MESSAGES.problem] : []),
    ...(budgetLimited ? [RETRIEVAL_LIMIT_MESSAGES.budget] : []),
    ...(retrieval.reporting.diagnostics.total > retrieval.reporting.diagnostics.returned
      ? [RETRIEVAL_LIMIT_MESSAGES.diagnostics] : []),
    ...(retrieval.reporting.omissions.total > retrieval.reporting.omissions.returned
      ? [RETRIEVAL_LIMIT_MESSAGES.omissions] : []),
  ];
  return messages.length > 0 ? messages.join(" ") : undefined;
}

type BrainRetrievalResult = {
  contractVersion: "1" | "3";
  wiki: {
    alias: string;
    schemaVersion: string;
    runtimeContract: string;
  };
  query: {
    question: string;
    shapes: string[];
    stateView: string;
    resolvedSeeds: string[];
    projectResolution?: BrainProjectResolution;
    temporal?: TemporalQuery;
  };
  evidence: BrainCompiledEvidence[];
  omissions: BrainCompilerOmission[];
  coverage: BrainCompilerCoverage;
  budget: BrainCompilerBudget;
  stop: BrainCompilerStop;
  continuation: Record<string, unknown> | null;
  diagnostics: BrainCompilerDiagnostic[];
  reporting: BrainCompilerReporting;
  selectedPages: string[];
  evidenceCount: number;
  candidateCount: number;
};

type BrainCompiledEvidence = {
  id: string;
  provider: string;
  route: string;
  page: string | null;
  source: string | null;
  locator: Record<string, unknown>;
  content: string;
  roles: string[];
  authoredState: string;
  derivedFlags: string[];
  authoritySignals: string[];
  selectionReasons: string[];
  byteCost: number;
  truncated: boolean;
  atomic: boolean;
};

type BrainCompilerDiagnostic = {
  code: string;
  message: string;
  provider: string | null;
  details: Record<string, unknown>;
};

type BrainCompilerOmission = {
  candidateId: string;
  reason: string;
  estimatedBytes: number | null;
};

type BrainCompilerReporting = {
  omissions: { total: number; returned: number };
  diagnostics: { total: number; returned: number };
};

type BrainCompilerStop = {
  reason: string;
  sufficient: boolean;
  detail: string;
};

